import { Component, OnInit } from '@angular/core';
import {HomeService} from '../home.service'
import {ActivatedRoute,Router,ParamMap} from '@angular/router'
import Swal from 'sweetalert2';
// import Swal from 'sweetalert2';
@Component({
  selector: 'app-passwordreset',
  templateUrl: './passwordreset.page.html',
  styleUrls: ['./passwordreset.page.scss'],
})
export class PasswordresetPage implements OnInit {
  isTextFieldType: boolean;
  togglePasswordFieldType(){
  this.isTextFieldType = !this.isTextFieldType;

}
token:any;
  constructor(private user:HomeService,private route:ActivatedRoute,private router:Router) {
    this.token=this.router.getCurrentNavigation().extractedUrl
    this.token=this.token.queryParams.token
  
   }

  ngOnInit() {
  }
  btnclick(password){
    console.log(password)
    if(password==null){
      Swal.fire('Please enter password here');
    }
    else{
    if(password.length<8){
    //  this.user.toast('This password is too short. It must contain at least 8 characters. This is too common','bottom',3000,'normalToast')
    Swal.fire('This password is too short. It must contain at least 8 characters')
    }
    else{
    this.user.confirmpassword(password,this.token).subscribe((res:any) =>{
      console.log(res);
      if(res.status== "OK"){
        Swal.fire('Password Updated Successfully')
      }
    })
  }
  }
  }

}
